  geom_histogram(bins = 20, col = "white", aes(x = body_mass_g, fill = species))

p2 <- ggplot(penguins) + 
  geom_histogram(bins = 20,  col = "white", aes(x = flipper_length_mm, fill = species))

p3 <- ggplot(penguins) + 
